index f4e384b..eea0050 100644
--- a/.pi/functions/README.md
+++ b/.pi/functions/README.md
@@ -55,7 +55,8 @@ result types from injected functions instead of copying their schemas.
   instead of being silently clamped. The only derived cap is the 285-second polling
   budget shared by `ci.waitForRun()` and `pr.waitForChecks()`: polls
   that would not fit after the initial delay are skipped, and a timeout reports both the
-  `attempts` made and `requestedAttempts`. A timeout never throws: both return
+  `attempts` made and `requestedAttempts`. Without `attempts`, both poll until the budget
+  is spent. A timeout never throws: both return
   `outcome: "pending"` with a `note` and a `hint` naming the call that continues the wait.
   Every `ci.waitForRun()` and `ci.waitForCommit()` result has `outcome` and `conclusion`
   (null while pending).
diff --git a/src/renderers/npm-result.ts b/src/renderers/npm-result.ts
index 89e5eb1..8faa9ca 100644
--- a/src/renderers/npm-result.ts
+++ b/src/renderers/npm-result.ts
@@ -104,7 +104,16 @@ function renderer(
   };
 }

-const run = renderer("run", (result) => ({ summary: `run, exit ${result.code}` }));
+// npm announces the script it runs: npm 10 prints "> name@version script" to stdout, and
+// npm 11+ prints "npm notice run name@version script" to stderr.
+const STDOUT_SCRIPT_BANNER = /^\s*> \S+@\S* (\S+)/;
+const STDERR_SCRIPT_BANNER = /^npm notice run \S+@\S* (\S+)$/m;
+const run = renderer("run", (result) => {
+  const script =
+    result.stdout.replace(ANSI_PATTERN, "").match(STDOUT_SCRIPT_BANNER)?.[1] ??
+    result.stderr.replace(ANSI_PATTERN, "").match(STDERR_SCRIPT_BANNER)?.[1];
+  return { summary: `run${script ? ` ${script}` : ""}, exit ${result.code}` };
+});
 const test = renderer("test", (result) => {
   const plain = result.stdout.replace(ANSI_PATTERN, "");
   const counts = plain.match(TEST_COUNTS_PATTERN)?.[1] ?? "";
diff --git a/src/renderers/result-summary.ts b/src/renderers/result-summary.ts
index 2e92f7c..b82f49f 100644
--- a/src/renderers/result-summary.ts
+++ b/src/renderers/result-summary.ts
@@ -62,7 +62,12 @@ export function describeResult(
   if (typeof value === "object") {
     const keys = Object.keys(value);
     const names = keys.slice(0, 3).join(", ");
-    return `Returned ${plural(keys.length, "field")}${names ? `: ${names}` : ""}`;
+    // The call completed, but its domain outcome may be pending or failed; show it (#390).
+    const outcome = Object.hasOwn(value, "outcome")
+      ? (value as { outcome: unknown }).outcome
+      : undefined;
+    const preview = typeof outcome === "string" ? inlineValue(outcome) : undefined;
+    return `Returned ${plural(keys.length, "field")}${names ? `: ${names}` : ""}${preview === undefined ? "" : ` · outcome: ${preview}`}`;
   }
   const preview = expanded ? undefined : inlineValue(value);
   return `Returned ${typeof value}${preview === undefined ? "" : `: ${preview}`}`;
